const sec=(l,b)=>`<section class="lab-section"><h2 class="lab-h2">${esc(l)}</h2><div class="lab-sec-body">${b}</div></section>`;
function view(r,t){
 if(r==='general')return `<div class="lab-fig"><img src="data:image/jpeg;base64," alt="Ketone shunt: BHB is converted by CNDP2 into BHB-amino acids"></div>`+t.generalGroups.map(g=>sec(g.h,g.p.map(x=>`<p class="lab-p">${esc(x)}</p>`).join(''))).join('');
 if(r==='lineas')return `<div class="lab-cards">`+t.lines.map((l,i)=>`<article class="lab-card"><div class="lab-tile lab-tile-${'abc'[i]}"><span>0${i+1}</span></div><p>${esc(l)}</p></article>`).join('')+`</div>`+sec(t.tabs.lines,`<p class="lab-p">${esc(t.methods)}</p>`);
 if(r==='miembros')return sec(t.membersLabel,`<article class="lab-member"><div class="lab-photo"><img src="data:image/jpeg;base64," alt="${esc(t.pi)}"></div><div><h3 class="lab-h3">${esc(t.pi)}</h3><p class="lab-p">${esc(t.piRole)}</p><p class="lab-muted">${esc(t.membersNote)}</p><a href="${MEMBER[lang]}" target="_blank" rel="noopener">Genyo-Universidad de Granada</a></div></article>`)+sec(t.toniLabel,`<article class="lab-member"><div class="lab-photo"><img src="data:image/jpeg;base64," alt="${esc(t.toni)}"></div><div><h3 class="lab-h3">${esc(t.toni)}</h3><p class="lab-p">${esc(t.toniRole)}</p><p class="lab-muted">${esc(t.toniJoin)}</p><p class="lab-muted">${esc(t.toniNote)}</p></div></article>`);
 if(r==='proyecto')return sec(t.projectLabel,`<p class="lab-lead">${esc(t.projectTitle)}</p><dl class="lab-facts">`+t.projectFacts.map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(f.value)}</dd></div>`).join('')+`</dl>`);
 if(r==='publicaciones')return sec(`${t.pubsLabel} · ${pubs.length}`,`<ol class="lab-pubs">`+pubs.map(p=>{const f=p.journal==='Cell'||p.journal==='Nature';const ti=p.link?`<a href="${p.link}" target="_blank" rel="noopener">${esc(p.title)}</a>`:esc(p.title);return `<li class="${f?'is-featured':''}"><div class="lab-pub-meta"><span class="lab-chip">${esc(p.journal||'—')}</span><span>${esc(p.date)}</span></div><p class="lab-pub-title">${ti}</p>${p.authors?`<p class="lab-muted">${esc(p.authors)}</p>`:''}</li>`}).join('')+`</ol>`);
 if(r==='noticias')return sec(t.followLabel,`<p class="lab-lead"><a href="https://x.com/mariadolores_mg" target="_blank" rel="noopener">@mariadolores_mg</a> · <a href="https://x.com/antonio_dg_" target="_blank" rel="noopener">@antonio_dg_</a></p>`)+sec('2026',`<p class="lab-p">- ${esc(t.newsLaunch)}</p>`)+sec('2025',`<p class="lab-p">- ${esc(t.newsRyc)}</p>`)+sec('2024',`<p class="lab-p">- <a href="https://brainresilience.stanford.edu/news/unlocking-secrets-ketosis" target="_blank" rel="noopener">unlocking the secrets of ketosis - Knight Initiative for Brain Resilience</a></p>`);
 return sec(t.joinLabel,`<p class="lab-lead">${esc(t.joinText)}</p><p class="lab-lead">${esc(t.joinStudents)}</p><p class="lab-lead">${esc(t.contactLabel)}: <a href="mailto:mariadolores.moya@genyo.es">mariadolores.moya@genyo.es</a></p>`);
}
function render(){
 const t=T[lang];const r=ROUTES.includes(location.hash.slice(2))?location.hash.slice(2):'general';
 document.documentElement.lang=lang;document.title=t.title;
 const other=lang==='es'?'en':'es';
 document.getElementById('app').innerHTML=`<div class="lab"><div class="lab-bar"><nav class="lab-nav" aria-label="${esc(t.title)}">`+ROUTES.map((x,i)=>`<a href="#/${x}"${x===r?' aria-current="page"':''}>${esc(t.tabs[KEYS[i]])}</a>`).join('')+`</nav><button type="button" class="lab-lang" id="lang" aria-label="${esc(t.langBtn)}" title="${esc(t.langBtn)}"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3.2 3 14.8 0 18M12 3c-3 3.2-3 14.8 0 18"/></svg><span>${lang.toUpperCase()}</span></button></div><header class="lab-hero"><p class="lab-kicker">${esc(t.fact)}</p><h1 class="lab-title">${esc(t.title)}</h1><p class="lab-intro">${esc(t.intro)}</p></header><main class="lab-main">${view(r,t)}</main><footer class="lab-foot">${esc(t.closing)} <a href="${SOURCE[lang]}" target="_blank" rel="noopener">${esc(t.source)}</a></footer></div>`;
 document.getElementById('lang').onclick=()=>{lang=other;localStorage.setItem('lang',lang);render();};
}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
